"""Rewritten answer options, so the correct answer is not recognisable by length alone.

OVERRIDES[(excerpt_id, question_index)] = [correct, wrong1, wrong2, wrong3]   (correct option first)
Applied by build_excerpts.py on top of excerpt_questions.QUESTIONS (the question text is unchanged).
"""
OVERRIDES = {}

def fix(sid, idx, correct, w1, w2, w3):
    OVERRIDES[(sid, idx)] = [correct, w1, w2, w3]

